import re

def evaluate_expr(expr_str, context):
    tokens = expr_str.replace('(', ' ').replace(')', ' ').split()
    stack = []
    for token in reversed(tokens):
        if token in ["bold", "cyan", "uppercase", "level_style"]:
            val = stack.pop()
            if token == "bold": stack.append(f"\033[1m{val}\033[0m")
            elif token == "cyan": stack.append(f"\033[36m{val}\033[0m")
            elif token == "uppercase": stack.append(val.upper())
            elif token == "level_style":
                v_upper = val.upper()
                if "INFO" in v_upper: stack.append(f"\033[1;32m{val}\033[0m")
                elif "WARN" in v_upper: stack.append(f"\033[1;33m{val}\033[0m")
                elif "ERROR" in v_upper: stack.append(f"\033[1;31m{val}\033[0m")
                elif "DEBUG" in v_upper: stack.append(f"\033[1;34m{val}\033[0m")
                elif "TRACE" in v_upper: stack.append(f"\033[1;36m{val}\033[0m")
                else: stack.append(f"\033[1;35m{val}\033[0m")
        elif token in ["fixed_size", "min_size"]:
            val = stack.pop()
            n = int(stack.pop())
            if token == "fixed_size":
                val_str = str(val)
                if len(val_str) > n: stack.append(val_str[:n])
                else: stack.append(val_str.rjust(n))
            else:
                val_str = str(val)
                if len(val_str) < n: stack.append(val_str.rjust(n))
                else: stack.append(val_str)
        elif token == "color_rgb":
            val = stack.pop()
            b = stack.pop()
            g = stack.pop()
            r = stack.pop()
            stack.append(f"\033[38;2;{r};{g};{b}m{val}\033[0m")
        else:
            if token.isdigit():
                stack.append(token)
            else:
                val = context.get(token, "")
                if val is None: val = ""
                stack.append(str(val))
    return stack[0] if stack else ""

