#!/usr/bin/env python3
import sys
import json
import argparse
import re
import datetime
import os

def parse_toml(content):
    config = {"level_map": {}}
    current_section = None
    for line in content.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"): continue
        if line.startswith("["):
            current_section = line.strip("[]")
            continue
        if "=" in line:
            k, v = line.split("=", 1)
            k = k.strip()
            v = v.strip()
            if current_section == "level_map":
                config["level_map"][k] = json.loads(v)
            else:
                if v.startswith("["):
                    config[k] = json.loads(v.replace("'", '"'))
                else:
                    config[k] = json.loads(v)
    return config

def load_config(path):
    if os.path.exists(path):
        with open(path, 'r') as f:
            return parse_toml(f.read())
    return None

