            items.append(f"{k_col}\033[2m: \033[0m{colorize_json(v)}")
        return "\033[2m{\033[0m" + "\033[2m, \033[0m".join(items) + "\033[2m}\033[0m"
    return str(val)

def substitute_placeholders(msg, ctx, fmt):
    try:
        prefix, suffix = fmt.split("key")
        p = re.escape(prefix) + r'(.+?)' + re.escape(suffix)

        def repl(m):
            k = m.group(1)
            val = None
            if isinstance(ctx, list):
                if k.isdigit() and int(k) < len(ctx):
                    val = ctx[int(k)]
            elif isinstance(ctx, dict):
                val = ctx.get(k)

            if val is not None:
                return colorize_json(val)
            else:
                return f"\033[2m{prefix}\033[0m\033[1;31m{k}\033[0m\033[2m{suffix}\033[0m"

        return re.sub(p, repl, str(msg))
    except Exception:
        return str(msg)

